     */
    public function testAutoGenerateWithAutoGenerateTitle()
    {
        $head = new Head();
        $option = [
            'autoGenerateTitle' => true,
            'autoGenerateDescription' => false,
            'separator' => ' | ',
            'iconSvg' => '.svg',
            'iconIco' => '.ico',
            'iconPng' => '.png',
            'robot' => 'index,follow',
            'colorTheme' => '#ffffff',
            'isDarkMode' => false,
